import base64,gzip,hashlib,json,os,stat,sys
from pathlib import Path
raw=gzip.decompress(base64.b64decode(BLOB))
if hashlib.sha256(raw).hexdigest()!=EXPECTED:raise SystemExit('Bundle checksum mismatch')
files=json.loads(raw)
if set(files)!=set(NAMES):raise SystemExit('Bundle file list mismatch')
if os.geteuid()!=0:raise SystemExit('Run as root on the selected Droplet')
base=Path('/var/lib/visionline-global-updater')
if not base.exists() and not base.is_symlink():base.mkdir(mode=0o700)
i=base.lstat()
if not stat.S_ISDIR(i.st_mode) or i.st_uid!=0 or stat.S_IMODE(i.st_mode)!=0o700:raise SystemExit('Unsafe updater directory')
if (base/'payload').exists() or (base/'payload').is_symlink():raise SystemExit('Updater already installed; use /root/ubuntu-global-updater.sh --status. Existing job preserved.')
payload=base/'payload';payload.mkdir(mode=0o700)
for name,value in files.items():
    data=base64.b64decode(value)
    fd=os.open(payload/name,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
    with os.fdopen(fd,'wb') as stream:stream.write(data);stream.flush();os.fsync(stream.fileno())
wrapper=Path('/root/ubuntu-global-updater.sh')
fd=os.open(wrapper,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o700)
with os.fdopen(fd,'w') as stream:
    stream.write('#!/bin/bash\nset -euo pipefail\nexec /usr/bin/python3 -B /var/lib/visionline-global-updater/payload/ubuntu_global.py "$@"\n')
    stream.flush();os.fsync(stream.fileno())
for directory in (payload,base,wrapper.parent):
    fd=os.open(directory,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
    try:os.fsync(fd)
    finally:os.close(fd)
os.execve('/bin/bash',['/bin/bash',str(wrapper),'--apply'],dict(PATH='/usr/sbin:/usr/bin:/sbin:/bin',HOME='/root',LANG='C',LC_ALL='C'))
